import json, os, urllib.request, re, time, redis, pika

def get_redis():
    return redis.Redis(host=os.environ.get("REDIS_HOST", "redis-state"), port=6379, decode_responses=True)

def get_mq_conn():
    creds = pika.PlainCredentials(os.environ.get('RABBITMQ_USER', 'sre'), os.environ.get('RABBITMQ_PASS', 'sre2026'))
    return pika.BlockingConnection(pika.ConnectionParameters(host=os.environ.get('RABBITMQ_HOST', 'rabbitmq'), virtual_host='sre-ops', credentials=creds))

def clean_output(text):
    """Remove tags <think> e evita que a IA ecoe as instruções do sistema."""
    text = re.sub(r'<think>.*?</think>', '', text, flags=re.DOTALL)
    # Remove linhas que parecem instruções de sistema (leaks)
    noise = ["você é", "sua missão", "persona:", "missão:", "instruções:", "lei universal", "responda em"]
    lines = [l for l in text.split('\n') if not any(n in l.lower() for n in noise)]
    return "\n".join(lines).strip()

def call_llm(skill_key, user_data, trace_id="global"):
    try:
        with open("/etc/governance/governance.md", "r") as f: gov = f.read()
        with open(f"/etc/skills/{skill_key}.md", "r") as f: skill = f.read()

        payload = {
            "model": "qwen2.5-7b-instruct",
            "messages": [
                {"role": "system", "content": f"{gov}\n{skill}"},
                {"role": "user", "content": f"EVIDÊNCIAS TÉCNICAS:\n{user_data}\n\nLembre-se: Responda em PT-BR e não repita instruções."}
            ],
            "temperature": 0.1
        }
        req = urllib.request.Request("http://172.18.0.1:1234/v1/chat/completions", data=json.dumps(payload).encode(), headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=120) as res:
            raw = json.loads(res.read())["choices"][0]["message"]["content"]
            return clean_output(raw)
    except Exception as e: return f"⚠️ Erro de IA: {e}"

def send_to_rocket(role, text, tmid=None):
    # FIX v14.7.3: truncar texto para evitar error-message-size-exceeded
    safe_text = (text[:4000] + '...') if len(text) > 4000 else text
    payload = {
        "roomId": "699b26601cf126f19882ef8d",
        "text": safe_text
    }
    if tmid: payload["tmid"] = tmid
    try:
        req = urllib.request.Request(f"{os.environ['RC_URL']}/api/v1/chat.postMessage", data=json.dumps(payload).encode(),
            headers={"X-Auth-Token": os.environ['RC_TOKEN'], "X-User-Id": os.environ['RC_USER_ID'], "Content-Type": "application/json"})
        with urllib.request.urlopen(req) as res:
            body = json.loads(res.read())
            if body.get("success"):
                return body["message"]["_id"]
            else:
                print(f"[RC ERROR] {body.get('error')}")
                return None
    except urllib.error.HTTPError as e:
        error_body = e.read().decode()
        print(f"[RC HTTP ERROR] {e.code}: {error_body}")
        return None
    except Exception as e:
        print(f"[RC CRITICAL] {e}")
        return None
